input.content:
// Follow-up gate for the WhatsApp / SMS support assistant.
// State is in memory only: it is lost on restart and not shared between processes.

const DAY_MS = 24 * 60 * 60 * 1000;

// Carrier and WhatsApp opt-out words, matched against the whole message.
const OPT_OUT_WORDS = new Set([
  'STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT', 'REVOKE',
  'OPT OUT', 'OPT-OUT', 'OPTOUT',
]);
// Words that turn messaging back on after an opt-out.
const OPT_IN_WORDS = new Set(['START', 'UNSTOP']);

// Upper-case, drop outer punctuation and collapse inner spaces, so "  Stop!! " becomes "STOP".
function normalize(text) {
  return String(text)
    .normalize('NFKC')
    .toUpperCase()
    .replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, '')
    .replace(/\s+/g, ' ');
}

const isValidDate = (d) => d instanceof Date && !Number.isNaN(d.getTime());

// One record per user: seen = has ever written to us, lastInboundAt = latest valid inbound time (ms),
// optedOut = last opt-out / opt-in keyword decided the state.
const users = new Map();

function recordFor(userId) {
  const key = String(userId);
  let r = users.get(key);
  if (!r) {
    r = { seen: false, lastInboundAt: null, optedOut: false };
    users.set(key, r);
  }
  return r;
}

export function onInbound(userId, text, at) {
  const r = recordFor(userId);
  r.seen = true;

  // Opt-out handling does not depend on the timestamp, so it is applied even when `at` is invalid.
  const word = normalize(text);
  if (OPT_OUT_WORDS.has(word)) r.optedOut = true;
  else if (OPT_IN_WORDS.has(word)) r.optedOut = false;

  if (isValidDate(at) && (r.lastInboundAt === null || at.getTime() > r.lastInboundAt)) {
    r.lastInboundAt = at.getTime();
  }
}

function block(rule) {
  return { allowed: false, rule };
}

export function check(userId, type, now) {
  if (type !== 'freeform' && type !== 'template') return block('unknown_type');
  if (!isValidDate(now)) return block('invalid_now');

  const r = users.get(String(userId));

  // Opt-out beats every other rule.
  if (r?.optedOut) return block('opted_out');

  // Customers who never wrote to us have never been contacted by the assistant.
  if (!r?.seen) return block('no_inbound_history');

  // Free text is only allowed inside 24 hours of the customer's last message.
  // Templates are pre-approved and may be sent after that window.
  if (type === 'freeform') {
    const open = r.lastInboundAt !== null && now.getTime() - r.lastInboundAt < DAY_MS;
    if (!open) return block('outside_24h_window');
  }

  return { allowed: true, rule: null };
}

input.command:
node --input-type=module -e '
import { onInbound, check } from "./bot.mjs";
const H = 3600e3, T0 = new Date("2026-10-23T09:00:00Z");
const at = (ms) => new Date(T0.getTime() + ms);
const out = [];
const ok = (name, got, want) => out.push([got === want ? "PASS" : "FAIL", name, JSON.stringify(got)]);
// never contacted
ok("never-written freeform", check("u1", "freeform", at(0)).rule, "no_inbound_history");
ok("never-written template", check("u1", "template", at(0)).allowed, false);
// inbound then freeform inside window -> allowed (one allowed case)
onInbound("u1", "Hi, my bill?", at(0));
ok("freeform inside 24h", check("u1", "freeform", at(1 * H)).allowed, true);
ok("template after 3 days", check("u1", "template", at(72 * H)).allowed, true);
ok("freeform after 25h", check("u1", "freeform", at(25 * H)).rule, "outside_24h_window");
// ordinary sentence with keyword is not opt-out
onInbound("u1", "I will stop by the shop today", at(2 * H));
ok("sentence containing STOP", check("u1", "template", at(3 * H)).allowed, true);
ok("stopping is not STOP", (onInbound("u2", "stopping", at(0)), check("u2", "template", at(1 * H)).allowed), true);
// opt-out variants, all forms
for (const [i, w] of ["  stop!! ", "Unsubscribe", "opt-out", "OPT OUT", "optout", "END.", "quit"].entries()) {
  const u = "o" + i;
  onInbound(u, "hello", at(0));
  onInbound(u, w, at(H));
  ok("opt-out " + JSON.stringify(w), check(u, "template", at(2 * H)).rule, "opted_out");
}
// START restores, but only for START/UNSTOP
onInbound("o0", "start", at(3 * H));
ok("START restores", check("o0", "template", at(4 * H)).allowed, true);
onInbound("o1", "please start", at(3 * H));
ok("ordinary text does not restore", check("o1", "template", at(4 * H)).rule, "opted_out");
ok("bad type", check("u1", "email", at(0)).rule, "unknown_type");
ok("bad now", check("u1", "freeform", "x").rule, "invalid_now");
let fails = 0;
for (const [s, n, g] of out) { console.log(s, n, g); if (s === "FAIL") fails++; }
console.log(fails ? fails + " FAILED" : "all passed");
'
